sys_script_include.script:
function AiToolUpdateStakeholder(vBusinessProcess,vUser,strNotes)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetValue = x_snc_devtools.GetValue;
	var GetUserRecord = x_snc_devtools.GetUserRecord;
	var GetStringValue = x_snc_devtools.GetStringValue;

	var grBusinessProcess = GetBusinessProcessRecord(vBusinessProcess);
	if (IsValidRecord(grBusinessProcess) == false)
	{
		return { message: 'The Business Process could not be found.' };
	}

	if (vUser == null)
	{
		vUser = gs.getUserID();
	}

	var grUser = GetUserRecord(vUser);
	if (IsValidRecord(grUser) == false)
	{
		return { message: 'Could not load the user record.' };
	}	

	var grStakeholder = GetStakeholderRecord(grBusinessProcess,grUser);
	if (IsValidRecord(grStakeholder) == false)
	{
		return { message: 'The user is not a stakeholder of the given Business Process.' };
	}	

	grStakeholder.notes = GetStringValue(strNotes);
	var bSuccess = grStakeholder.update();

	if (bSuccess == false)
	{
		return { message: 'Updating the Stakeholder notes failed!' };
	}
	return { message: 'Updating the Stakeholder notes was successful!' };
}
